screens=[('home','概览','首页 · 数字先行',home),('ledger','流水','流水 · 一点分类',ledger),('stats','统计','统计 · 消费去向',stats),('credit','信用卡','信用卡 · 还款优先',credit),('match','核对关联','关联 · 两边原文',match),('settings','分类与规则','设置 · 分类有序',settings)]
body='<div class="board" id="board"><div class="boardhead"><div><h1>少读一点，看清每一笔。</h1><p>本地记账 · 精简设计提案 / 2026.06.25</p></div><span>设计原型 · 全部为合成数据</span></div><div class="proto-tabs">'+''.join(f'<button data-go="{id}">{title}</button>' for id,title,_,_ in screens)+'</div><div class="grid">'+''.join(f'<div class="screenwrap {"active" if id=="home" else ""}"><p class="caption">{i+1:02d}　{caption}</p><section class="phone" id="{id}"><div class="status"><span>9:41</span><span>▰ ▮▮ ◒</span></div><header class="head"><h2>{title}</h2><button aria-label="页面信息" data-info="静态可交互设计；不读取短信、不保存手机账本。">{ "⌕" if id=="ledger" else "⋯"}</button></header><main>{content}</main>{nav(id if id!="match" else "credit")}</section></div>' for i,(id,title,caption,content) in enumerate(screens))+'</div></div><dialog class="dialog" id="modal"><h3 id="modal-title"></h3><div id="modal-body"></div><button class="primary" id="close">完成</button></dialog><div class="toast" hidden id="toast" aria-live="polite"></div>'
js='''const $=s=>document.querySelector(s);const modal=$('#modal');function openModal(title,body){$('#modal-title').textContent=title;$('#modal-body').innerHTML=body;modal.showModal()}function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,1800)}document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{let target=document.getElementById(b.dataset.go);document.querySelectorAll('.screenwrap').forEach(x=>x.classList.toggle('active',x.contains(target)));target.scrollIntoView({block:'center',behavior:'smooth'})});document.querySelectorAll('[data-info]').forEach(b=>b.onclick=()=>openModal('详情','<p>'+b.dataset.info+'</p>'));$('#close').onclick=()=>modal.close();let selectedTag;document.querySelectorAll('[data-classify]').forEach(b=>b.onclick=()=>{selectedTag=b;openModal('选择分类','<div class="categorygrid">'+['餐饮','购物','交通','日用','订阅','其他','转账','还款','待分类'].map(n=>'<button data-choice="'+n+'">'+n+'</button>').join('')+'</div>');modal.querySelectorAll('[data-choice]').forEach(c=>c.onclick=()=>{selectedTag.textContent=c.dataset.choice+'⌄';selectedTag.classList.remove('pending');modal.close();toast('已标记 · 原文保留')})});$('#batch').onclick=()=>{$('#batch-label').textContent='已选 2 笔';$('#batch').textContent='取消';toast('演示：批量选择两笔流水')};$('#partial').onclick=()=>openModal('候选范围','<p>默认：同卡、同币种、同金额</p><button class="chip" data-partial-choice>其他金额 · 部分退款</button>');$('#confirm-link').onclick=()=>{toast('已关联最早一笔 · 可在详情解除');$('#confirm-link').textContent='已关联 · 解除';$('#confirm-link').onclick=()=>{$('#confirm-link').textContent='已解除';toast('已解除 · 保留审计')}};$('#new-category').onclick=()=>{openModal('新建分类','<input aria-label="分类名称" placeholder="分类名称" style="width:100%;padding:12px;margin:0 0 16px">')};'''
font=TTFont('/usr/share/fonts/opentype/noto/NotoSansCJK-Regular.ttc',fontNumber=2);opt=subset.Options();opt.flavor='woff';s=subset.Subsetter(options=opt);s.populate(text=body+js);s.subset(font);font.flavor='woff';font.save(P/'font.woff')
fontcss="@font-face{font-family:Ledger;src:url(data:font/woff;base64,"+b64encode((P/'font.woff').read_bytes()).decode()+") format('woff')}"
html='<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>本地记账 · 精简设计</title><style>'+fontcss+css+'</style><body>'+body+'<script>'+js+'</script></body></html>'
(P/'ledger-clear-v3.html').write_text(html)
print('built',len(html))
